// The wiki follows the registry's real lazy loaders, including Form's merged
// module. This checks generated bytes; help-staleness.mjs separately measures
// screenshot provenance and coverage of user-visible changes.
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { Script } from 'node:vm'
import ts from 'typescript'

const ROOT = resolve(import.meta.dirname, '../..')
export const WIKI_PAGES = [
  'Getting-around', 'Importing-files', 'Sketch', 'Model', 'Form', 'Relief',
  'Setup-Stock-and-Workholding', 'Toolpaths-2.5D', 'Toolpaths-3D', 'Nesting',
  'Simulate', 'Post-Process', 'Control', 'Probing', 'Settings',
]

// The plan's workspace names differ from Help's 14 learning-path categories.
// Keep the split/merge visible here rather than duplicate topics or hand prose.
const CATEGORY_PAGES = {
  'getting-started': 'Getting-around',
  'workspaces-viewport': 'Getting-around',
  'import-geometry': 'Importing-files',
  sketching: 'Sketch',
  modeling: 'Model',
  'setups-stock-wcs': 'Setup-Stock-and-Workholding',
  'cam-operations': 'Toolpaths-2.5D',
  'tools-holders': 'Toolpaths-2.5D',
  nesting: 'Nesting',
  simulation: 'Simulate',
  'posting-gcode': 'Post-Process',
  machine: 'Control',
  settings: 'Settings',
  troubleshooting: 'Getting-around',
}
const TOPIC_PAGES = {
  'model-relief': 'Relief',
  'probing-tab': 'Probing',
  'probe-routines': 'Probing',
  'mesh-viewer': 'Probing',
  'import-refusals': 'Importing-files',
  'sketch-conflicts': 'Sketch',
  'outdated-after-open': 'Toolpaths-2.5D',
  'missing-toolpath': 'Toolpaths-2.5D',
}

export function pageForTopic(topic) {
  if (TOPIC_PAGES[topic.id]) return TOPIC_PAGES[topic.id]
  if (topic.category === 'modeling' && topic.id.startsWith('form-')) return 'Form'
  if (topic.category === 'cam-operations' && topic.id.endsWith('-3d')) return 'Toolpaths-3D'
  const page = CATEGORY_PAGES[topic.category]
  if (!page) throw new Error(`Unmapped Help category: ${topic.category} (${topic.id})`)
  return page
}

/** Isolated TS module cache per run: no build output, app bootstrap, or global
 * loader hooks. Dynamic imports compile to this same local require, so adding
 * a registry loader automatically adds its topics to the generated corpus. */
export async function loadHelp(sourceRoot = ROOT) {
  const helpDir = resolve(sourceRoot, 'src/help')
  const cache = new Map()
  function load(file) {
    if (cache.has(file)) return cache.get(file).exports
    const module = { exports: {} }
    cache.set(file, module)
    const code = ts.transpileModule(readFileSync(file, 'utf8'), {
      fileName: file,
      compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
    }).outputText
    function localRequire(specifier) {
      const base = resolve(dirname(file), specifier)
      if (!specifier.startsWith('.') || !base.startsWith(`${helpDir}/`) && !base.startsWith(`${helpDir}\\`)) {
        throw new Error(`Help import outside src/help: ${specifier}`)
      }
      const target = existsSync(`${base}.ts`) ? `${base}.ts` : resolve(base, 'index.ts')
      return load(target)
    }
    new Script(code, { filename: file }).runInNewContext({ module, exports: module.exports, require: localRequire })
    return module.exports
  }
  const registry = load(resolve(helpDir, 'registry.ts'))
  const { HELP_CATEGORIES: categories } = load(resolve(helpDir, 'categories.ts'))
  const topics = []
  for (const category of categories) topics.push(...await registry.loadCategoryTopics(category.id))
  const index = registry.helpIndex()
  const ids = topics.map(topic => topic.id)
  if (new Set(ids).size !== ids.length) throw new Error('Duplicate topic id in Help registry loaders')
  if (index.length !== ids.length || index.some(entry => !topics.some(topic => topic.id === entry.id && topic.category === entry.category))) {
    throw new Error('Help registry index and loaded topic ids/categories differ')
  }
  const unknownLoaders = Object.keys(registry.CATEGORY_LOADERS).filter(id => !categories.some(category => category.id === id))
  if (unknownLoaders.length) throw new Error(`Help loaders without a category: ${unknownLoaders.join(', ')}`)
  return { topics, index, categories }
}

function text(value) {
  // Help body strings are plain text in the app; Markdown must not interpret
  // constraint symbols, shortcuts, angle brackets or table pipes as markup.
  return value.replace(/[\\`*_\[\]<>|]/g, '\\$&').replace(/\r?\n/g, '<br>')
}

function safeName(value) {
  if (!/^[a-z0-9][a-z0-9._-]*$/i.test(value) || value.includes('..')) {
    throw new Error(`Unsafe Help asset name: ${value}`)
  }
  return value
}

export function renderWiki(topics, assetRoot = ROOT) {
  const groups = new Map(WIKI_PAGES.map(page => [page, []]))
  const destinations = new Map()
  const images = new Map()
  const imageSources = new Map()
  for (const topic of topics) {
    safeName(topic.id)
    if (destinations.has(topic.id)) throw new Error(`Duplicate Help topic: ${topic.id}`)
    const page = pageForTopic(topic)
    destinations.set(topic.id, page)
    groups.get(page).push(topic)
  }
  function renderImage(topic, slot) {
    const image = topic.images.find(image => image.slot === slot)
    if (!image || image.status !== 'done') return '' // same debt policy as HelpCenterModal
    const file = safeName(image.file)
    const source = `public/help/${topic.id}/${file}`
    const bytes = readFileSync(resolve(assetRoot, source))
    if (/\.(mp4|webm)$/i.test(file)) {
      // The wiki is a sibling of blob/main in the public repository URL.
      // Keep the account out of generated prose and the video in public/help.
      const url = `../blob/main/public/help/${topic.id}/${file}`
      return `[Video: ${text(image.alt)}](${url}) - Watch in the app: open Help and search for "${text(topic.title)}".`
    }
    const target = `images/${topic.id}/${file}`
    images.set(target, bytes)
    imageSources.set(target, source)
    return `![${text(image.alt)}](${target})`
  }
  function section(topic, block) {
    switch (block.kind) {
      case 'paragraph': return text(block.text)
      case 'steps': return block.steps.map((step, i) => `${i + 1}. ${text(step)}`).join('\n')
      case 'tip': return `> **Tip:** ${text(block.text)}`
      case 'warning': return `> **Warning:** ${text(block.text)}`
      case 'heading': return `<a id="${topic.id}-${safeName(block.anchor)}"></a>\n\n### ${text(block.text)}`
      case 'image': return renderImage(topic, block.slot)
      case 'table': {
        const row = cells => `| ${cells.map(text).join(' | ')} |`
        const rows = block.rows.map(item => {
          const cells = item.cells.map(text)
          if (item.anchor) cells[0] = `<a id="${topic.id}-${safeName(item.anchor)}"></a>${cells[0]}`
          return `| ${cells.join(' | ')} |`
        })
        return [row(block.columns), row(block.columns.map(() => '---')), ...rows].join('\n')
      }
      default: throw new Error(`Unknown Help section kind: ${block.kind} (${topic.id})`)
    }
  }
  const pages = new Map()
  for (const [name, group] of groups) {
    if (!group.length) throw new Error(`Wiki page has no Help topics: ${name}`)
    const lines = [
      '<!-- Generated from the in-app Help by tools/release/help-to-wiki.mjs. Do not edit by hand. -->',
      '', `# ${name.replaceAll('-', ' ')}`, '',
      ...group.map(topic => `- [${text(topic.title)}](#${topic.id})`), '',
    ]
    for (const topic of group) {
      lines.push(`<a id="${topic.id}"></a>`, '', `## ${text(topic.title)}`, '', text(topic.summary), '')
      for (const block of topic.sections) {
        const rendered = section(topic, block)
        if (rendered) lines.push(rendered, '')
      }
      if (topic.relatedTopicIds.length) {
        const links = topic.relatedTopicIds.map(id => {
          const related = topics.find(candidate => candidate.id === id)
          if (!related) throw new Error(`Missing related Help topic: ${topic.id} -> ${id}`)
          // GitHub wiki URLs use page names without the source .md suffix.
          return `[${text(related.title)}](${destinations.get(id)}#${id})`
        })
        lines.push(`See also: ${links.join(', ')}.`, '')
      }
    }
    pages.set(`${name}.md`, lines.join('\n'))
  }
  return { pages, images, imageSources, destinations }
}

export async function generateWiki(sourceRoot = ROOT, assetRoot = sourceRoot) {
  const help = await loadHelp(sourceRoot)
  return { ...help, ...renderWiki(help.topics, assetRoot) }
}

export function staleWikiFiles(generated, wikiRoot = resolve(ROOT, 'docs/wiki')) {
  const stale = []
  for (const [file, expected] of [...generated.pages, ...generated.images]) {
    const target = resolve(wikiRoot, file)
    if (!existsSync(target) || !statSync(target).isFile()) {
      stale.push(file)
      continue
    }
    const actual = readFileSync(target)
    // Git checks Markdown out as CRLF on the Windows desk, LF on Spark.
    // Compare canonical text bytes; images always use their exact source bytes.
    const canonical = generated.pages.has(file) ? Buffer.from(actual.toString('utf8').replaceAll('\r\n', '\n')) : actual
    if (!canonical.equals(Buffer.from(expected))) stale.push(file)
  }
  return stale
}

export function writeWiki(generated, wikiRoot = resolve(ROOT, 'docs/wiki')) {
  for (const [file, bytes] of [...generated.pages, ...generated.images]) {
    const target = resolve(wikiRoot, file)
    mkdirSync(dirname(target), { recursive: true })
    writeFileSync(target, bytes)
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const args = process.argv.slice(2)
    const check = args.includes('--check')
    let sourceRoot = ROOT
    for (let i = 0; i < args.length; i++) {
      if (args[i] === '--check') continue
      if (args[i] === '--source-root' && args[i + 1]) sourceRoot = resolve(args[++i])
      else throw new Error('usage: node tools/release/help-to-wiki.mjs [--check] [--source-root <dir>]')
    }
    const generated = await generateWiki(sourceRoot, ROOT)
    if (check) {
      const stale = staleWikiFiles(generated)
      if (stale.length) throw new Error(`Stale wiki files: ${stale.join(', ')}. Run npm run wiki:generate.`)
    } else writeWiki(generated)
    console.log(`wiki: ${check ? 'current' : 'generated'} - ${generated.pages.size} pages, ${generated.topics.length} topics, ${generated.images.size} images`)
  } catch (error) {
    console.error(error.message)
    process.exitCode = 1
  }
}
